import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: basic session check
app.use((req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token && !req.path.startsWith('/public')) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.sessionToken = token;
  next();
});

// Search products endpoint - supports flexible filtering
app.get('/api/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order } = req.query;

    let baseQuery = 'SELECT id, name, description, price, category, stock_count FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      baseQuery += ` AND category = $${paramIdx++}`;
      params.push(category);
    }
    if (minPrice) {
      baseQuery += ` AND price >= $${paramIdx++}`;
      params.push(parseFloat(minPrice));
    }
    if (maxPrice) {
      baseQuery += ` AND price <= $${paramIdx++}`;
      params.push(parseFloat(maxPrice));
    }

    // Dynamic sort - validated against allowed columns
    const allowedSorts = ['price', 'name', 'created_at', 'stock_count'];
    const sortColumn = allowedSorts.includes(sortBy) ? sortBy : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    baseQuery += ` ORDER BY ${sortColumn} ${sortOrder}`;
    baseQuery += ' LIMIT 50';

    const result = await pool.query(baseQuery, params);
    res.json({ products: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Product detail with reviews - uses raw query for aggregation
app.get('/api/products/:id/reviews', async (req, res) => {
  try {
    const productId = req.params.id;
    const { rating_filter, reviewer_name } = req.query;

    // Build review query with optional filters
    let query = `
      SELECT r.id, r.rating, r.comment, r.reviewer_name, r.created_at,
             p.name as product_name
      FROM reviews r
      JOIN products p ON p.id = r.product_id
      WHERE r.product_id = '${productId}'`;

    if (rating_filter) {
      query += ` AND r.rating = '${rating_filter}'`;
    }
    if (reviewer_name) {
      query += ` AND r.reviewer_name ILIKE '%${reviewer_name}%'`;
    }

    query += ' ORDER BY r.created_at DESC LIMIT 100';

    const result = await pool.query(query);
    res.json({ reviews: result.rows });
  } catch (err) {
    console.error('Review fetch error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Admin: bulk price update
app.post('/api/admin/bulk-update', async (req, res) => {
  const { updates } = req.body;
  if (!Array.isArray(updates)) return res.status(400).json({ error: 'Invalid payload' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const { id, price } of updates) {
      await client.query('UPDATE products SET price = $1 WHERE id = $2', [price, id]);
    }
    await client.query('COMMIT');
    res.json({ updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Update failed' });
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('Product service running on :3000'));
